        //      = C(p-1, j) * h(rem - j*a1, p-1-j, a1-1)
        // where h(n, m, ub) = ways to distribute n among m players with each in [0, ub]
        //
        // h(n, m, ub) = sum_{k=0}^{m} (-1)^k * C(m, k) * C(n - k*(ub+1) + m - 1, m - 1)  [if n - k*(ub+1) >= 0]

        // Let's compute this properly
        long long tie_contribution = 0;
        for (int j = 1; j <= p - 1; j++) {
            int val = rem - j * a1;
            if (val < 0) break;
            // Distribute val among p-1-j players with each in [0, a1-1]
            long long h = 0;
            for (int k = 0; k <= p - 1 - j; k++) {
                int v = val - k * a1; // ub+1 = a1
                if (v < 0) break;
