                    h = (h + term) % MOD;
                } else {
                    h = (h - term + MOD) % MOD;
                }
            }
            long long g = C[p - 1][j] * h % MOD;
            tie_contribution = (tie_contribution + g * inv(j + 1)) % MOD;
        }

        win = (win + ways_less + tie_contribution) % MOD;
    }

    long long ans = win * inv(total) % MOD;
    cout << ans << endl;

    return 0;
}
