int C[MAX_S * 2][MAX_P];

void precompute() {
    inv[1] = 1;
    for (int i = 2; i < MAX_S * 2; ++i) {
        inv[i] = (MOD - 1LL * (MOD / i) * inv[MOD % i] % MOD) % MOD;
    }
    for (int n = 0; n < MAX_S * 2; ++n) {
        C[n][0] = 1;
        for (int k = 1; k < MAX_P && k <= n; ++k) {
            C[n][k] = (C[n - 1][k - 1] + C[n - 1][k]) % MOD;
        }
    }
}

