                    if (p - 1 - k == 0) {
                        if (v == 0) {
                            ways_tie = (ways_tie + 1LL * sign * term) % MOD;
                        }
                    }
                    continue;
                }
                term = 1LL * term * C[v + p - 2 - k][p - 2 - k] % MOD;
                ways_tie = (ways_tie + 1LL * sign * term) % MOD;
            }
            // Contribution: C(p-1, k) * (1/(k+1)) * ways_tie
            int prob = 1LL * inv[k + 1] * ways_tie % MOD;
            tie_contribution = (tie_contribution + 1LL * C[p - 1][k] * prob) % MOD;
        }

        // Total contribution for this x
        long long contrib = (ways_strict + tie_contribution) % MOD;
        numerator = (numerator + contrib) % MOD;
    }

    // Probability = numerator / total
    int ans = 1LL * numerator * inv[total] % MOD;
    if (ans < 0) ans += MOD;
    cout << ans << endl;

    return 0;
}
