#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;
const int MAX_S = 5005;
const int MAX_P = 105;

int mod_inv(int a, int m = MOD) {
    int m0 = m;
    int y = 0, x = 1;
    if (m == 1) return 0;
    while (a > 1) {
        int q = a / m;
        int t = m;
        m = a % m;
        a = t;
        t = y;
        y = x - q * y;
        x = t;
    }
    if (x < 0) x += m0;
    return x;
}

int main() {
    int p, s, r;
    cin >> p >> s >> r;

    // dp[p][s] = number of ways to distribute s scores among p players
    // with each player having at least 0
    static int dp[MAX_P][MAX_S];
    memset(dp, 0, sizeof(dp));
    dp[0][0] = 1;
    for (int i = 0; i < p; i++) {
        for (int j = 0; j <= s; j++) {
            if (dp[i][j] == 0) continue;
            for (int k = 0; k + j <= s; k++) {
                dp[i+1][j+k] = (dp[i+1][j+k] + dp[i][j]) % MOD;
            }
        }
    }

    // Total number of valid states
    int total = dp[p][s];

    // Now calculate the number of winning states
    // For Hasan to win, either:
    // 1. a1 > all other players
    // 2. a1 is tied with some players, and he is chosen as winner

    // We need to count for each possible a1 (from r to s)
    // the number of ways the other p-1 players can have scores
    // such that a1 is the maximum or tied for maximum

    int win = 0;

    for (int a1 = r; a1 <= s; a1++) {
        int rem = s - a1;
        if (rem < 0) break;

        // Number of ways other p-1 players can sum to rem
        // with each having at most a1 (so a1 is max or tied)

        // First, count ways where all others <= a1
        // Then subtract ways where all others <= a1-1 (so a1 is strictly max)

        // Ways where all others <= a1:
        // This is dp[p-1][rem] but with constraint each <= a1
        // We need a different dp for this

        // Let's compute ways where sum = rem, p-1 players, each in [0, a1]
        // and ways where sum = rem, p-1 players, each in [0, a1-1]

        static int dp2[MAX_P][MAX_S];
        static int dp3[MAX_P][MAX_S];

        // dp2: each player in [0, a1]
        memset(dp2, 0, sizeof(dp2));
        dp2[0][0] = 1;
        for (int i = 0; i < p-1; i++) {
            for (int j = 0; j <= rem; j++) {
                if (dp2[i][j] == 0) continue;
                for (int k = 0; k <= a1 && j + k <= rem; k++) {
                    dp2[i+1][j+k] = (dp2[i+1][j+k] + dp2[i][j]) % MOD;
                }
            }
        }

        // dp3: each player in [0, a1-1]
        memset(dp3, 0, sizeof(dp3));
        dp3[0][0] = 1;
        for (int i = 0; i < p-1; i++) {
            for (int j = 0; j <= rem; j++) {
                if (dp3[i][j] == 0) continue;
                for (int k = 0; k < a1 && j + k <= rem; k++) {
                    dp3[i+1][j+k] = (dp3[i+1][j+k] + dp3[i][j]) % MOD;
                }
            }
        }

        int ways_all_le_a1 = dp2[p-1][rem];
        int ways_all_le_a1_minus_1 = dp3[p-1][rem];

        // Ways where a1 is strictly max: ways_all_le_a1_minus_1
        // Ways where a1 is tied for max: ways_all_le_a1 - ways_all_le_a1_minus_1

        int strict_max = ways_all_le_a1_minus_1;
        int tied_max = (ways_all_le_a1 - ways_all_le_a1_minus_1 + MOD) % MOD;

        // For strict max, Hasan wins with probability 1
        win = (win + (long long)strict_max) % MOD;

        // For tied max, need to count how many players are tied
        // If k players are tied (including Hasan), probability is 1/k
        // We need to sum over all possible numbers of tied players

        // Actually, let's think differently.
        // For tied_max cases, we need to count for each possible number of 
        // other players that also scored exactly a1

        // Let's say m other players scored exactly a1, and the rest scored less
        // Then total tied = m + 1 (including Hasan)
        // Probability of winning = 1/(m+1)

        // We need to count, for each m from 0 to p-1:
        // number of ways where exactly m of the other p-1 players scored a1,
        // and the rest scored <= a1-1, and total sum = rem

        // For m other players scoring exactly a1:
        // remaining (p-1-m) players score in [0, a1-1]
        // sum of remaining = rem - m*a1

        for (int m = 0; m <= p-1; m++) {
            int remaining_sum = rem - m * a1;
            if (remaining_sum < 0) break;

            int remaining_players = p - 1 - m;

            // Ways for remaining_players to sum to remaining_sum, each in [0, a1-1]
            static int dp4[MAX_P][MAX_S];
            memset(dp4, 0, sizeof(dp4));
            dp4[0][0] = 1;
            for (int i = 0; i < remaining_players; i++) {
                for (int j = 0; j <= remaining_sum; j++) {
                    if (dp4[i][j] == 0) continue;
                    for (int k = 0; k < a1 && j + k <= remaining_sum; k++) {
                        dp4[i+1][j+k] = (dp4[i+1][j+k] + dp4[i][j]) % MOD;
                    }
                }
            }

            int ways = dp4[remaining_players][remaining_sum];

            // Choose which m players scored a1: C(p-1, m)
            // But we need to compute this combination
            // Actually, we should use precomputed combinations or compute on the fly

            // Let's compute C(p-1, m)
            long long comb = 1;
            for (int i = 0; i < m; i++) {
                comb = comb * (p - 1 - i) % MOD;
                comb = comb * mod_inv(i + 1) % MOD;
            }

            int prob = mod_inv(m + 1); // 1/(m+1)

            win = (win + (long long)ways * comb % MOD * prob) % MOD;
        }
    }

    // Probability = win / total
    int ans = (long long)win * mod_inv(total) % MOD;
    cout << ans << endl;

    return 0;
}
