    for (int i = 0; i <= s; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % mod;
    }
    vector<ll> inv(s + 1);
    for (int i = 1; i <= s; ++i) inv[i] = modpow(i, mod - 2);
    vector<ll> fact(s + 1), ifact(s + 1);
    fact[0] = ifact[0] = 1;
    for (int i = 1; i <= s; ++i) {
        fact[i] = fact[i - 1] * i % mod;
        ifact[i] = ifact[i - 1] * inv[i] % mod;
    }
    auto comb = [&](int a, int b) -> ll {
        if (a < 0 || b < 0 || a < b) return 0;
        return fact[a] * ifact[b] % mod * ifact[a - b] % mod;
    };
    ll total = 0, win = 0;
    for (int a1 = r; a1 <= s; ++a1) {
        int rem = s - a1;
        if (rem < 0) break;
        ll ways = 0;
        for (int k = 0; k <= n; ++k) {
            int t = rem - k * a1;
            if (t < 0) break;
            ll c = comb(n, k) * comb(t + n - 1, n - 1) % mod;
            if (k & 1) ways = (ways - c + mod) % mod;
            else ways = (ways + c) % mod;
        }
        total = (total + ways) % mod;
        ll win_ways = 0;
        for (int k = 0; k <= n; ++k) {
            int t = rem - k * (a1 + 1);
            if (t < 0) break;
            ll c = comb(n, k) * comb(t + n - 1, n - 1) % mod;
            if (k & 1) win_ways = (win_ways - c + mod) % mod;
            else win_ways = (win_ways + c) % mod;
        }
        win = (win + win_ways) % mod;
        ll tie_ways = (ways - win_ways + mod) % mod;
        win = (win + tie_ways * inv[n + 1]) % mod;
    }
    cout << win * modpow(total, mod - 2) % mod << '\n';
    return 0;
