    int p, s, r;
    cin >> p >> s >> r;

    if (p == 1) {
        cout << 1 << endl;
        return 0;
    }

    // dp[i][j] = number of ways to distribute j points among i players (each >= 0)
    vector<vector<int>> dp(p, vector<int>(s + 1, 0));

    // Base case: 0 players, 0 points
    dp[0][0] = 1;

    for (int i = 1; i < p; i++) {
        for (int j = 0; j <= s; j++) {
            for (int k = 0; k <= j; k++) {
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD;
            }
        }
    }

    // Total valid distributions where a1 >= r and sum = s
    // a1 can be from r to s
    // remaining sum = s - a1, distributed among p-1 players
    long long total = 0;
    for (int a1 = r; a1 <= s; a1++) {
        int rem = s - a1;
        if (rem >= 0) {
            total = (total + dp[p - 1][rem]) % MOD;
        }
    }

