    // Case 2: a1 == max, and Hasan is chosen as winner (1/k probability where k is number of players with max score)

    long long win = 0;

    // Case 1: a1 > all others
    // a1 from r to s, others from 0 to a1-1, sum of others = s - a1
    for (int a1 = r; a1 <= s; a1++) {
        int rem = s - a1;
        if (rem < 0) continue;

        // Count ways to distribute rem among p-1 players, each <= a1 - 1
        // Use inclusion-exclusion or direct DP
        // dp2[i][j] = ways to distribute j among i players, each <= a1-1
        vector<vector<int>> dp2(p, vector<int>(rem + 1, 0));
        dp2[0][0] = 1;

        for (int i = 1; i <= p - 1; i++) {
            for (int j = 0; j <= rem; j++) {
                for (int k = 0; k <= min(j, a1 - 1); k++) {
                    dp2[i][j] = (dp2[i][j] + dp2[i - 1][j - k]) % MOD;
                }
            }
        }

        win = (win + dp2[p - 1][rem]) % MOD;
    }

