        // = coefficient of x^rem in (1 + x + ... + x^(a1-1))^n
        // = sum_{k=0}^{n} (-1)^k * C(n, k) * C(rem - k*a1 + n - 1, n - 1)
        ll ways = 0;
        for (int k = 0; k <= n; k++) {
            int val = rem - k * a1;
            if (val < 0) break;
