    // For each a1 from r to s:
    //   remaining = s - a1
    //   distribute remaining among p-1 players, each <= a1
    //   and at least one player has score == a1
    //   probability of winning = 1 / (number of players with score == a1)
    //   But we need to count each sequence weighted by 1/(number of top scorers)

    for (int a1 = r; a1 <= s; a1++) {
        int rem = s - a1;
