            int val = rem - k * (a1 + 1);
            if (val < 0) break;
            int sign = (k % 2 == 0) ? 1 : (mod - 1);
            ways_all = (ways_all + (ll)sign * C(n, k) % mod * C(val + n - 1, n - 1)) % mod;
        }

        // Number of ways where all players < a1 (i.e., max < a1)
        // = coefficient of x^rem in (1 + x + ... + x^(a1-1))^n
        ll ways_less = 0;
        for (int k = 0; k <= n; k++) {
            int val = rem - k * a1;
            if (val < 0) break;
            int sign = (k % 2 == 0) ? 1 : (mod - 1);
            ways_less = (ways_less + (ll)sign * C(n, k) % mod * C(val + n - 1, n - 1)) % mod;
