    }
    int total = dp[p - 1][s];
    int win = 0;
    for (int a1 = r; a1 <= s; a1++) {
        int rem = s - a1;
        if (rem < 0)
            continue;
        int ways = dp[p - 2][rem];
        int cnt = 0;
        for (int a2 = 0; a2 <= rem; a2++) {
            if (a2 < a1) {
                cnt = (cnt + dp[p - 3][rem - a2]) % MOD;
            }
        }
        win = (win + (1LL * ways * cnt) % MOD) % MOD;
        if (a1 == 0)
            continue;
        int tie = dp[p - 2][rem];
        tie = (tie - cnt + MOD) % MOD;
        win = (win + (1LL * tie * mod_inv(2)) % MOD) % MOD;
    }
    cout << (1LL * win * mod_inv(total)) % MOD << endl;
    return 0;
}
