```cpp
#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int p, s, r;
    cin >> p >> s >> r;

    // Precompute factorials and inverse factorials up to s
    vector<long long> fact(s + 1, 1), inv_fact(s + 1, 1);
    for (int i = 1; i <= s; ++i) {
        fact[i] = fact[i - 1] * i % MOD;
    }
    inv_fact[s] = 1;
    long long inv_s = 1;
    long long pow_s = s;
    long long e = MOD - 2;
    while (e > 0) {
        if (e & 1) inv_s = inv_s * pow_s % MOD;
        pow_s = pow_s * pow_s % MOD;
        e >>= 1;
    }
    inv_fact[s] = inv_s;
    for (int i = s - 1; i >= 0; --i) {
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD;
    }

    auto comb = [&](int n, int k) -> long long {
        if (n < 0 || k < 0 || k > n) return 0;
        return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD;
    };

    // Precompute inverse of p
    long long inv_p = 1;
    long long pow_p = p;
    long long e2 = MOD - 2;
    while (e2 > 0) {
        if (e2 & 1) inv_p = inv_p * pow_p % MOD;
        pow_p = pow_p * pow_p % MOD;
        e2 >>= 1;
    }

    // Precompute powers of inv_p
    vector<long long> inv_p_pow(s + 1, 1);
    for (int i = 1; i <= s; ++i) {
        inv_p_pow[i] = inv_p_pow[i - 1] * inv_p % MOD;
    }

    // Compute dp[i][j]: number of ways to distribute j into i non-negative integers
    vector<vector<long long>> dp(p, vector<long long>(s + 1, 0));
    dp[0][0] = 1;
    for (int i = 1; i < p; ++i) {
        for (int j = 0; j <= s; ++j) {
            for (int k = 0; k <= j; ++k) {
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD;
            }
        }
    }

    long long total = 0;
    for (int a1 = r; a1 <= s; ++a1) {
        int rem = s - a1;
        if (rem < 0) continue;

        // Compute C(rem + p - 2, p - 2)
        long long ways = comb(rem + p - 2, p - 2);

        // Compute probability of a1 being the winner
        long long prob = 0;
        for (int k = 0; k <= p - 1; ++k) {
            int m = p - 1 - k;
            if (m < 0) break;
            long long c = comb(p - 1, k);
            long long term = c * dp[m][rem] % MOD;
            term = term * inv_p_pow[k] % MOD;
            prob = (prob + term) % MOD;
        }

        total = (total + ways * prob) % MOD;
    }

    // Compute total_states = C(s - r + p - 1, p - 1)
    long long total_states = comb(s - r + p - 1, p - 1);

    // Compute answer = total / total_states mod MOD
    long long inv_total_states = 1;
    long long pow_ts = total_states;
    long long e3 = MOD - 2;
    while (e3 > 0) {
        if (e3 & 1) inv_total_states = inv_total_states * pow_ts % MOD;
        pow_ts = pow_ts * pow_ts % MOD;
        e3 >>= 1;
    }

    long long ans = total * inv_total_states % MOD;
    cout << ans << endl;
    return 0;
}
